def render_lesson_content(source_summary, explanation, example, exercise, objective):
    """Build editable lesson HTML while clearly labeling slide-derived content."""
    return """<article class=\"python-lesson\">
<section class=\"source-outline\"><h3>Course proposal outline</h3><p>Summary of the topic described in MADERA_SAM_PROPOSAL.PPTX:</p><p>{source}</p></section>
<section><h3>Teaching material authored for this module</h3><p>{explanation}</p><h4>Worked example</h4><pre><code>{example}</code></pre></section>
<section><h3>Try it</h3><p>{exercise}</p><p><strong>Learning check:</strong> {objective}</p></section>
</article>""".format(
        source=escape(source_summary),
        explanation=escape(explanation),
        example=escape(example),
        exercise=escape(exercise),
        objective=escape(objective),
    )
